import assert from 'node:assert/strict';
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { Tracer } from '../../src/index.ts';
import { SQLiteRepository } from '../../src/persistence/sqlite.ts';
const destination = 'projects/tracer/configuration-full-verification-execution.json';
assert.ok(!existsSync(destination));
const hash = value => createHash('sha256').update(value).digest('hex');
const artifact = path => ({ path, sha256: hash(readFileSync(path)) });
const audit = JSON.parse(readFileSync('projects/tracer/configuration-acceptance-audit.json'));
const original = JSON.parse(readFileSync('projects/tracer/configuration-change-original-case.json'));
const prepared = JSON.parse(readFileSync('output/configuration-change/original-follow-through-prepared.json'));
const opened = JSON.parse(readFileSync('output/configuration-change/original-controlled-verification-opened.json'));
const candidate = JSON.parse(readFileSync('projects/tracer/configuration-final-candidate-manifest.json'));
const log = readFileSync(audit.gates.log.path);
assert.equal(hash(log), audit.gates.log.sha256); assert.match(String(log), /219 passed/); assert.match(String(log), /ℹ pass 714/);
for (const file of candidate.files) {
  assert.equal(hash(readFileSync(file.path)), file.sha256, file.path);
  assert.equal(hash(execFileSync('git', ['show', 'HEAD:' + file.path], { maxBuffer: 16000000 })), file.sha256, file.path);
}
for (const c of audit.criteria) for (const file of [...c.tests, ...c.reports]) assert.equal(hash(readFileSync(file.path)), file.sha256, file.path);
for (const file of original.sourceStates) assert.equal(hash(execFileSync('git', ['show', original.originalCommit + ':' + file.path])), file.sha256, file.path);
for (const x of prepared.observed) assert.equal('sha256:' + hash(readFileSync(x.path)), x.observation.hash, x.path);
const repository = new SQLiteRepository('projects/tracer/tracer.sqlite');
const researchReport = JSON.parse(readFileSync('projects/tracer/configuration-research-follow-through.json'));
const researchRepository = new SQLiteRepository(researchReport.preservation.onlineBackup);
try {
  let observations = 0;
  const t = new Tracer(repository, undefined, async () => { observations++; throw Error('Final acceptance reads must not observe content'); });
  const before = await t.exportProject(); assert.equal(before.projectRevision, 177);
  assert.deepEqual(await t.configurations.get(prepared.before.id), prepared.before);
  assert.deepEqual(await t.configurations.get(prepared.after.id), prepared.after);
  assert.deepEqual(await t.configurations.get(original.legacyConfiguration.id), prepared.originalLegacy);
  const comparison = await t.configurations.compare({ beforeId: prepared.before.id, afterId: prepared.after.id });
  assert.deepEqual(comparison, prepared.comparison);
  assert.equal(comparison.content.filter(x => x.content === 'different').length, 6);
  assert.equal(comparison.content.filter(x => x.content === 'same').length, 1);
  const pages = []; let after;
  do {
    const query = { beforeId: prepared.before.id, afterId: prepared.after.id, limit: 1, ...(after ? { after } : {}) };
    const page = await t.configurations.compareDependencies(query);
    pages.push({ query, digest: page.discovery.digest, discovery: page.discovery, receipts: page.evaluations.items.map(x => ({ id: x.receipt.id, inclusion: x.inclusion, beforeState: x.before.state, afterState: x.after.state, dependencyChange: x.dependencyChange })) });
    after = page.evaluations.nextAfter;
  } while (after);
  const unique = pages.flatMap(p => p.receipts.map(x => x.id)); assert.equal(new Set(unique).size, unique.length);
  const verification = await t.verification.analyze(opened.selection);
  assert.equal(verification.view.scope.target.configurationId, prepared.after.id);
  assert.equal(verification.view.scope.basis.criteria.length, 12); assert.equal(verification.executions.length, 0); assert.equal(verification.ready, false);
  assert.deepEqual(verification.view.scope.basis.criteria.map(x => x.quote), audit.criteria.map(x => x.id + ': ' + x.expected));
  const assessment = await t.changeAssessments.analyze(prepared.selection);
  assert.equal(assessment.obligations.filter(x => x.state === 'accounted').length, 8);
  assert.equal(assessment.obligations.reduce((n, o) => n + o.openActions, 0), 1);
  const real = JSON.parse(readFileSync('output/configuration-change/real-follow-through-prepared.json'));
  const queueCase = await t.verification.analyze(real.selection), queueAssessment = await t.changeAssessments.analyze(real.assessment);
  assert.equal(queueCase.view.case.version, 14); assert.equal(queueCase.completion.state, 'verified'); assert.equal(queueCase.executions.length, 4);
  assert.equal(queueCase.executions[0].results[0].outcome, 'failed'); assert.equal(queueCase.executions[0].results[1].outcome, 'not_run');
  assert.equal(queueAssessment.completion.state, 'completed'); assert.equal(queueAssessment.obligations.length, 18); assert.equal(queueAssessment.discovery, 'current');
  const research = new Tracer(researchRepository);
  const researchExport = await research.exportProject(); assert.equal(hash(JSON.stringify(researchExport)), researchReport.preservation.canonicalExportSha256);
  assert.equal((await research.verification.analyze(researchReport.verification.selection)).completion.state, 'verified');
  const ra = await research.changeAssessments.analyze(researchReport.assessment.selection); assert.equal(ra.completion.state, 'completed'); assert.equal(ra.obligations.length, 7); assert.equal(ra.discovery, 'current');
  const means = ['before', 'after'].map(name => {
    const values = readFileSync('projects/tracer/research-cohort/' + name + '.csv', 'utf8').trim().split('\n').slice(1).map(Number);
    assert.equal(values.length, 5); assert.ok(values.every(Number.isFinite));
    return values.reduce((a, b) => a + b, 0) / values.length;
  }); assert.deepEqual(means, [12, 13]);
  assert.equal(observations, 0); assert.deepEqual(await t.exportProject(), before);
  const actual = [
    'Exact native/topology/content capture, original-intent recovery and explicit unknowns pass final-source checks. Actual original and final captures remain identical after subsequent native updates; original legacy capture is preserved.',
    'Actual selected pair comparison is identical at native177 to its original result. Fixed selected facts remain independent of later native/evidence state; executable fixtures prove incompatible/partial/legacy/schema and unavailable-capture behavior.',
    'Actual pair retains 11 before/13 after members, exact versions and values, including six changed content states and one unchanged persistence state. Final-source assertions cover additions/removals, version-only edits, missing/null, nested JSON, array order and removal versus live deletion.',
    'Actual two selected engineering mappings retain exact v1 endpoints. Executed historical-topology and comparison fixtures additionally prove relinking, removed/parallel/self-loop links, role/selector/state changes and unknown legacy topology.',
    'All nine after observations match retained exact candidate/procedure bytes; seven genuine pre-edit source hashes match their retained original Git blobs. Six fingerprints differ and one is equal; newly selected material remains unknown-before. Zero observer calls occurred. Hashes do not assert retained SQLite bytes or passage relevance.',
    'Actual dependency discovery exhausts all one-row pages without duplicate receipts or writes. Explicit declared identities, selected fields/paths/direct links/content and excluded/unknown scope remain qualified. Executed tests prove stale/foreign cursors and complete refusal at population/payload/work bounds.',
    'Actual REQ-011 assessment is completed/current for 18 candidates, research for 7; original phase outcomes and judgments are preserved. The original pair has eight individually accounted historical phases and one explicitly open root action. This controlled verification supplies its required proof; final assessment control outputs are audited separately after conclusion.',
    'Actual REQ-011 case v14 retains four activities including failed/not_run, selected exact-target passing execution and historical conclusions. Research case v9 independently verifies B/C/B after-target inputs and rejects before-only proof. Executed target/support tests prove governing/accounting/unknown/review/provenance limits; the current twelve-criterion case is correctly not ready before recording and selecting results.',
    'Final-source core/typed HTTP/client/CLI recovery and rejection scenarios pass. Actual restored capture recovery through all three interfaces adds no duplicate writes and preserves old command outcomes; captured queries and controls share application services.',
    'The original independent fresh-agent task completed all 8 candidates with current discovery, zero actions and exact-after verification. Candidate/loading/unknown wording findings are addressed. The actual-project read-only follow-up found the hidden project-property issue; the final production 390px regression and 219 browser scenarios pass after its correction. Agent evidence is distinct from representative-human validation.',
    'The genuine original capture-enhancement change is retained as an explicit retrospective before and exact committed after, with six changed source fingerprints, unchanged persistence bytes and no rewrite of legacy captures. Its affected real REQ-011 follow-through and materially different numeric research task have controlled verified conclusions and complete assessments. Original-pair verification/assessment control outputs follow these measured results and are checked before full-goal promotion.',
    'Current format11/schema7 and preservation proofs retain identities, native/evidence history, old outcomes and prior application contracts; no physical migration was needed. Deterministic export and online/restored backup checks pass. All 781 implementation/test fingerprints match committed candidate bafed89, 714 unit/219 browser/workbench and unchanged quality gates pass. Owning contracts/usage/status preserve scope and validation distinctions; final publication and post-control full-goal audit remain required before completion.'
  ];
  const report = { date: '2026-10-28', status: 'performed_software_acceptance_results_for_controlled_recording', requirement: 'REQ-035', method: 'VER-035', candidateCommit: execFileSync('git', ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim(), candidateManifest: artifact('projects/tracer/configuration-final-candidate-manifest.json'), originalSpecification: artifact('projects/tracer/configuration-change-specification.json'), methodDeclaration: artifact('projects/tracer/configuration-original-follow-through-method.json'), selectedPair: { beforeId: prepared.before.id, afterId: prepared.after.id, digest: comparison.basis.digest }, controlledVerification: opened.selection, nativeRevisionRead: 177, verification: audit.gates, results: audit.criteria.map((c, i) => ({ criterionId: c.id, outcome: 'passed', actual: actual[i], rationale: c.coverage + '. Evidence is scoped software verification; no generic receipt label, graph coverage or human/physical/regulatory claim substitutes for these checks.', tests: c.tests, reports: c.reports })), actualReads: { dependencyPages: pages, originalBeforeSourceBlobsMatch: 7, afterObservationHashesMatch: 9, committedImplementationFilesMatch: candidate.files.length, observerCalls: observations, unchangedExport: true, researchMeans: means, queueCaseVersion: 14, queueActivities: 4, queueAssessmentCandidates: 18, researchCaseVersion: 9, researchAssessmentCandidates: 7 }, documentation: ['docs/architecture.md', 'docs/developer-reference.md', 'docs/ux-plan.md', 'docs/checkpoint.md'].map(artifact), qualification: 'These are the measured software-capability results to record in the exact-target case. Recording alone is not controlled conclusion or completed assessment. Original-pair conclusion, action completion, assessment closure, final register publication and post-publication preservation/full-goal audit must all be checked before declaring goal completion. Outside declared engineering scope remains unknown; representative-human, physical/regulatory, new-backend and arbitrary-scale validation are excluded.', procedure: { path: 'output/configuration-change/audit-final-candidate.mjs', sha256: hash(readFileSync('output/configuration-change/audit-final-candidate.mjs')), source: readFileSync('output/configuration-change/audit-final-candidate.mjs', 'utf8') } };
  writeFileSync(destination, JSON.stringify(report, null, 2) + '\n');
  console.log(JSON.stringify({ status: report.status, criteria: report.results.length, actualDependencyReceipts: unique.length, observerCalls: observations, candidateFiles: candidate.files.length }));
} finally { repository.close(); researchRepository.close(); }
